CREATE TABLE IF NOT EXISTS lesson_completions (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, lesson_id TEXT NOT NULL, best_score REAL NOT NULL CHECK(best_score>=0 AND best_score<=1), passed_at BIGINT NOT NULL, PRIMARY KEY(user_id,lesson_id));
CREATE TABLE IF NOT EXISTS guided_attempts (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, id TEXT NOT NULL, lesson_id TEXT NOT NULL, version INTEGER NOT NULL, question_id TEXT NOT NULL, assisted INTEGER NOT NULL CHECK(assisted IN (0,1)), skipped INTEGER NOT NULL CHECK(skipped IN (0,1)), result TEXT NOT NULL, created_at BIGINT NOT NULL, PRIMARY KEY(user_id,id));
CREATE TABLE IF NOT EXISTS quiz_sessions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, config TEXT NOT NULL, pool TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('active','finished')), cursor INTEGER NOT NULL DEFAULT 0 CHECK(cursor>=0), cycle INTEGER NOT NULL DEFAULT 1 CHECK(cycle>=1), revision INTEGER NOT NULL DEFAULT 0, target INTEGER NOT NULL CHECK(target>=1), summary TEXT, created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS quiz_sessions_user_status ON quiz_sessions(user_id,status,updated_at);
CREATE TABLE IF NOT EXISTS quiz_items (session_id TEXT NOT NULL REFERENCES quiz_sessions(id) ON DELETE CASCADE, id TEXT NOT NULL, position INTEGER NOT NULL CHECK(position>=0), cycle INTEGER NOT NULL CHECK(cycle>=1), question_id TEXT NOT NULL, question_version INTEGER NOT NULL, question_snapshot TEXT NOT NULL, options TEXT NOT NULL, choice_id TEXT, feedback TEXT, correct INTEGER CHECK(correct IN (0,1)), answered_at BIGINT, PRIMARY KEY(session_id,position), UNIQUE(session_id,id), FOREIGN KEY(question_id,question_version) REFERENCES exercise_versions(id,version));
CREATE INDEX IF NOT EXISTS quiz_items_session_question ON quiz_items(session_id,question_id);
CREATE TABLE IF NOT EXISTS activity_events (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, id TEXT NOT NULL, created_at BIGINT NOT NULL, PRIMARY KEY(user_id,id));
CREATE INDEX IF NOT EXISTS activity_user_time ON activity_events(user_id,created_at);
